"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["35854"],{962191(e){e.exports=JSON.parse('{"id":10466,"title":"\u8BBA\u6587\u6846\u67B6\u56FE\u751F\u6210","description":"You are a professor-level researcher skilled in drawing scientific architecture diagrams for top computer vision conferences such as CVPR, ICCV, and NeurIPS.\\n\\nNow that you fully understand my research on pose-guided image generation and multimodal pose expansion, you must design a high-quality scientific architecture diagram that illustrates the core logical workflow of the proposed framework.\\n\\nThe diagram should clearly present the complete pipeline of pose-guided image generation, including:\\n\\n\u2022 input pose representation (2D skeleton or 3D pose)\\n\u2022 reference appearance image\\n\u2022 pose conditioning module\\n\u2022 pose-aware feature encoding\\n\u2022 generative model unit (diffusion / GAN / control network)\\n\u2022 candidate generation stage\\n\u2022 structural consistency evaluation\\n\u2022 multimodal filtering\\n\u2022 final generated image output\\n\\nThe architecture should visually demonstrate the closed-loop logic of the framework:\\n\\nInput \u2192 Pose Analysis \u2192 Conditional Generation \u2192 Candidate Results \u2192 Structure Consistency Screening \u2192 Final Output\\n\\nEach module should be drawn as an independent block with clear titles.\\n\\nPossible visual units include:\\n\\n\u2022 stacked rectangles\\n\u2022 trapezoid processing blocks\\n\u2022 encoder-decoder shapes\\n\u2022 dual-branch pipelines\\n\u2022 feature fusion modules\\n\\nArrows must clearly indicate the direction of information flow.\\n\\nEach module should contain internal submodules such as:\\n\\npose encoder\\nappearance encoder\\npose alignment unit\\ngeneration module\\nconsistency scoring module\\n\\nThe diagram should look like a real architecture figure from a CVPR paper.\\n\\nDesign requirements:\\n\\n\u2022 publication-ready scientific diagram\\n\u2022 vector style diagram\\n\u2022 balanced layout\\n\u2022 no large empty areas\\n\u2022 clearly separated modules\\n\u2022 readable labels\\n\u2022 color-coded module groups\\n\u2022 logical pipeline connections\\n\\nEach module should have its own background color to improve readability and emphasize modular structure.\\n\\nThe layout must be suitable for academic papers and maintain a clean and professional scientific appearance.","owner":"sunfengbin0","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:39:00.466Z"}')}}]);